// newSeriesAPI builds a handler over a fresh store with two serial libraries
// and returns the router, the store, and both library ids.
func newSeriesAPI(t *testing.T) (http.Handler, *store.Store, int64, int64) {
	t.Helper()
	st := openAPIStore(t)
	h := New(Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
		return scan.Result{}, nil
	}})
	libA, err := st.CreateLibrary(context.Background(), "serial", "/media/ongoing", "Ongoing")
	if err != nil {
		t.Fatalf("CreateLibrary A: %v", err)
	}
	libB, err := st.CreateLibrary(context.Background(), "serial", "/media/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary B: %v", err)
	}
	return h, st, libA, libB
}

// seedSeries puts one series row into a library with the given relative path,
// document, and status, and returns the stored row (with its minted ser_ id).
func seedSeries(t *testing.T, st *store.Store, libraryID int64, relPath, docJSON, status string) store.Series {
	t.Helper()
	if err := st.PutSeries(context.Background(), store.Series{
		ModuleID: "serial", LibraryID: libraryID, RelativePath: relPath,
		Document: json.RawMessage(docJSON), SchemaVersion: 1, Status: status,
	}); err != nil {
		t.Fatalf("PutSeries %s: %v", relPath, err)
	}
	got, err := st.GetSeriesByPath(context.Background(), libraryID, relPath)
	if err != nil {
		t.Fatalf("GetSeriesByPath %s: %v", relPath, err)
	}
	return got
}

// TestSeriesRoutesBrowseGated covers 4.1: the three series routes live in the
// browse group — a client-role principal reaches all of them (the injected
// client principal is the only way to mint that role today; see
// role_gating_test.go), the real New wiring serves them for the admin token,
// the list filters by the required integer library, and a missing or
// non-integer ?library= is 400 bad_request with the canonical error body. An
// unauthenticated call is 401 (authN precedes authZ).
func TestSeriesRoutesBrowseGated(t *testing.T) {
	h, st, libA, libB := newSeriesAPI(t)

	dirDoc := `{"parsed":{"serial_record":true,"backing":"directory","dir_name_raw":"Show"},"ffprobe":{}}`
	seriesA := seedSeries(t, st, libA, "Show", dirDoc, "pending")
	seedSeries(t, st, libB, "Other", dirDoc, "pending")

	t.Run("client_role_reaches_all_three_routes", func(t *testing.T) {
		// No resolver mints RoleClient yet, so the client-authorization path is
		// exercised via the synthetic-principal injector over the REAL
		// mountV1Routes wiring (the TestNew_RoleGating seam).
		client := gatingRouter(Deps{
			AdminToken: adminToken, Store: st,
			Scan: func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
		}, RoleClient)
		for _, path := range []string{
			"/api/v1/series?library=" + itoa64(libA),
			"/api/v1/series/" + seriesA.ID,
			"/api/v1/series/" + seriesA.ID + "/episodes",
		} {
			resp := doRequest(t, client, http.MethodGet, path, "", "no-authmw")
			resp.Body.Close()
			if resp.StatusCode == http.StatusForbidden || resp.StatusCode == http.StatusUnauthorized {
				t.Fatalf("client role %s: status = %d (browse group must admit client)", path, resp.StatusCode)
			}
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("client role %s: status = %d, want 200", path, resp.StatusCode)
			}
		}
	})

	t.Run("list_filters_by_library", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(libA), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var lr seriesListResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode seriesListResponse: %v", err)
		}
		if len(lr.Items) != 1 || lr.Items[0].ID != seriesA.ID {
			t.Fatalf("items = %+v, want exactly series %s of library %d", lr.Items, seriesA.ID, libA)
		}
		if lr.Items[0].ModuleID != "serial" || lr.Items[0].LibraryID != libA || lr.Items[0].RelativePath != "Show" {
			t.Fatalf("seriesDTO = %+v, want the seeded row fields", lr.Items[0])
		}
	})

	t.Run("get_series_full_document_opaque", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+seriesA.ID, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var dr seriesResponse
		if err := json.NewDecoder(resp.Body).Decode(&dr); err != nil {
			t.Fatalf("decode seriesResponse: %v", err)
		}
		if dr.Series.ID != seriesA.ID || dr.Series.Status != "pending" {
			t.Fatalf("seriesResponse = %+v", dr.Series)
		}
		// The document arrives opaque but complete: the marker facts survive
		// the round-trip (INV-full-document).
		var doc struct {
			Parsed map[string]json.RawMessage `json:"parsed"`
		}
		if err := json.Unmarshal(dr.Series.Document, &doc); err != nil {
			t.Fatalf("document is not JSON: %v", err)
		}
		if string(doc.Parsed["dir_name_raw"]) != `"Show"` {
			t.Fatalf("parsed.dir_name_raw = %s, want \"Show\"", doc.Parsed["dir_name_raw"])
		}
	})

	t.Run("missing_library_param_400", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" || eb.Error.Retryable {
			t.Fatalf("error body = %+v, want bad_request/non-retryable", eb.Error)
		}
	})

	t.Run("non_integer_library_400", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library=abc", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})

	t.Run("unauthenticated_401", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(libA), "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusUnauthorized)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unauthenticated" {
			t.Fatalf("error code = %q, want unauthenticated", eb.Error.Code)
		}
	})

	t.Run("write_methods_not_mounted", func(t *testing.T) {
		// Read-only surface: no write endpoint exists for series (the admin
		// mutating group is untouched) — a POST to the collection is 405/404
		// method-not-registered, never a 2xx.
		resp := doRequest(t, h, http.MethodPost, "/api/v1/series", `{"library":1}`, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
			t.Fatalf("POST /series status = %d, want a non-2xx (no write endpoint)", resp.StatusCode)
		}
	})
}

// TestSeriesEpisodesAndNotFound covers 4.2: the episodes endpoint returns the
// series' episode items in the item wire shape (direct children only for a
// directory-backed series, exact match for a file-backed one), and an unknown
// series id yields 404 not_found with the canonical error body on BOTH {id}
// routes.
func TestSeriesEpisodesAndNotFound(t *testing.T) {
	h, st, libID, _ := newSeriesAPI(t)
	ctx := context.Background()

	show := seedSeries(t, st, libID, "Show",
		`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`, "ready")
	seedItem(t, st, libID, "e1", "Show/Show S01E01.mkv")
	seedItem(t, st, libID, "e2", "Show/Show S01E02.mkv")
	// A grandchild belongs to a deeper level, not to this serial's episode list.
	seedItem(t, st, libID, "deep", "Show/Extras/extra.mkv")
	// A sibling serial's episode must not leak in.
	other := seedSeries(t, st, libID, "Other",
		`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`, "pending")
	seedItem(t, st, libID, "o1", "Other/Other S01E01.mkv")

	t.Run("episodes_directory_backed", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+show.ID+"/episodes", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var ir itemsResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemsResponse: %v", err)
		}
		want := []string{"itm_e1", "itm_e2"} // relative_path order, depth-1 only
		if len(ir.Items) != len(want) {
			t.Fatalf("episodes = %+v, want exactly %v", ir.Items, want)
		}
		for i, id := range want {
			got := ir.Items[i]
			if got.ID != id || got.LibraryID != libID || got.MediaType != "tv" {
				t.Fatalf("episodes[%d] = %+v, want item %s in the item wire shape", i, got, id)
			}
			if got.FileID == "" || got.RelativePath == "" || len(got.Document) == 0 {
				t.Fatalf("episodes[%d] missing item wire fields: %+v", i, got)
			}
		}
	})

	t.Run("episodes_file_backed", func(t *testing.T) {
		stray := seedSeries(t, st, libID, "The_Ribbon_Hero_[ONA].mkv",
			`{"parsed":{"serial_record":true,"backing":"file"},"ffprobe":{}}`, "pending")
		seedItem(t, st, libID, "stray", "The_Ribbon_Hero_[ONA].mkv")

		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+stray.ID+"/episodes", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var ir itemsResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemsResponse: %v", err)
		}
		if len(ir.Items) != 1 || ir.Items[0].ID != "itm_stray" {
			t.Fatalf("file-backed episodes = %+v, want exactly itm_stray", ir.Items)
		}
	})

	t.Run("sibling_series_episodes_isolated", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+other.ID+"/episodes", "", adminToken)
		defer resp.Body.Close()
		var ir itemsResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemsResponse: %v", err)
		}
		if len(ir.Items) != 1 || ir.Items[0].ID != "itm_o1" {
			t.Fatalf("sibling episodes = %+v, want exactly itm_o1 (no cross-serial leak)", ir.Items)
		}
	})

	t.Run("unknown_series_404_on_both_id_routes", func(t *testing.T) {
		for _, path := range []string{
			"/api/v1/series/ser_999_deadbeefdeadbeef",
			"/api/v1/series/ser_999_deadbeefdeadbeef/episodes",
		} {
			resp := doRequest(t, h, http.MethodGet, path, "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusNotFound {
				t.Fatalf("%s status = %d, want %d", path, resp.StatusCode, http.StatusNotFound)
			}
			if eb := decodeError(t, resp); eb.Error.Code != "not_found" || eb.Error.Retryable {
				t.Fatalf("%s error body = %+v, want not_found/non-retryable", path, eb.Error)
			}
		}
	})

	t.Run("episodes_of_library_without_items_empty_not_null", func(t *testing.T) {
		// A series whose episodes are not yet persisted yields {"items":[]},
		// the same empty-array contract as the items listing.
		libID2, err := st.CreateLibrary(ctx, "serial", "/media/empty", "Empty")
		if err != nil {
			t.Fatalf("CreateLibrary empty: %v", err)
		}
		lonely := seedSeries(t, st, libID2, "Lonely",
			`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`, "pending")
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+lonely.ID+"/episodes", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var raw map[string]json.RawMessage
		if err := json.NewDecoder(resp.Body).Decode(&raw); err != nil {
			t.Fatalf("decode raw: %v", err)
		}
		if string(raw["items"]) != "[]" {
			t.Fatalf("episodes items = %s, want [] (not null)", string(raw["items"]))
		}
	})
}
